mapper.sql:
		WHERE od.ENT_CODE = #{srchEntCode}
		
			AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP'
			AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'EXP'
			AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP'
			AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'EXP'
		
		
			AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
			AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
		
		
		
		
			
			
			AND dbo.Cryptography(od.OD_JOB_NO, od.${srchNoType}_ENC, 1) LIKE CONCAT('%',#{srchNo},'%')
			
			
			
				
				AND dbo.Cryptography(od.OD_JOB_NO, od.${srchNoType}_ENC, 1) IN (#{item})
				
				
				AND dbo.Cryptography(od.OD_JOB_NO, od.${srchNoType}_ENC, 1) = #{srchNo}
				
			
			
			
		
		
			
			
			AND od.${srchNoType} LIKE CONCAT('%',#{srchNo},'%')
			
			
			
				
				AND od.${srchNoType} IN (#{item})
				
				
				AND od.${srchNoType} = #{srchNo}
				
			
			
			
		
		
		
		
			
			
			AND od.${srchCusType} LIKE CONCAT('%',#{srchCus},'%')
			
			
			AND od.${srchCusType} = #{srchCus} 
			
			 
		
		
			AND od.${srchCusType} = #{srchDeliveryCode} 
		
		
			AND od.${srchCusType} = #{srchCbCode} 
		
		
				
			
			AND od.${srchOrigDestType} LIKE CONCAT('%',#{srchOrigDest},'%')
			
			
			AND od.${srchOrigDestType} = #{srchOrigDest} 
			
			
											
		
			AND od.VESSEL_FLIGHT = #{srchVesselFlight}
			
		
			AND (1 = 0
			
				
				
				OR od.CD_TYPE = #{item}
				
				
				OR od.CD_TYPE IN ('N', 'B') OR ad.DROP_YN = 'Y'
				
				
			
			)
				
		
			
				
				 AND ad.CLEARANCE_YN = 'Y'
				
				
				 AND ISNULL(od.CLEARANCE_VIOLATION_CODE, '') != '' 
				
				
				 AND ISNULL(ad.CLEARANCE_YN, '') IN('', 'N')
				
			
		
		
		AND hld.HOLD_CODE = #{srchHoldCode}
		

		
		
			AND(1 = 0
			
			OR od.INSPECTION_YN = #{srchInspectionYn}
			
			
			OR ad.SE_INSPECTION_YN = #{srchSeInspectionYn}
			
			
			OR ad.XRAY_YN = #{srchXrayYn}
			
			
			OR ad.DROP_YN = #{srchDropYn}
			
			)
		
		
			
				AND od.INSPECTION_YN = #{srchInspectionYn}
			
			
				AND ad.SE_INSPECTION_YN = #{srchSeInspectionYn}
			
			
				AND ad.XRAY_YN = #{srchXrayYn}
			
			
				AND ad.DROP_YN = #{srchDropYn}
			
		
		
		
		
		
		
		
			AND ISNULL(ad.WH_LOCATION, '') != ''
		
		
			AND ad.WH_LOCATION = #{srchWhLocation}
		
		
			
		
			AND(
				
					
					ad.CARRYIN_DATE IS NOT NULL
					ad.CARRYIN_DATE IS NULL
					ad.CARRYOUT_DATE IS NOT NULL
					ad.CARRYOUT_DATE IS NULL
					(ad.CARRYIN_DATE IS NOT NULL AND ad.CARRYOUT_DATE IS NULL)
					ad.WH_CARRYOUT_DATE IS NOT NULL
					ad.WH_CARRYOUT_DATE IS NULL
					ad.STOCK_DATE_TIME IS NOT NULL
					
				
			)
		
		
		AND ad.DELIVERY_STATUS = #{srchDeliveryStatus}
		
		
		AND od.BL_TYPE_MH = 'H'

mapper.select:
/* CoioMapper.selectCoioSummaryList : 반입/반출(summury) 조회 */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT MAX(odAdd.CARRYIN_DATE) AS CARRYIN_DATE , MAX(od.MBL_NO) AS MBL_NO , MAX(od.ORIG_CODE) AS ORIG_CODE , MAX(od.DEST_CODE) AS DEST_CODE , MAX(od.CUST_CODE_LV1) AS AGENT_CODE , MAX(od.SHIPPER_NAME) AS SHIPPER_NAME , MAX(od.AR_DATE) AS AR_DATE , COUNT(od.HBL_NO) AS HBL_CNT , COUNT(CASE WHEN ISNULL(od.CD_TYPE, '') = 'Y' THEN 1 END) AS CD_TYPE_YY_CNT , COUNT(CASE WHEN ISNULL(od.CD_TYPE, '') = 'N' THEN 1 END) AS CD_TYPE_NN_CNT , COUNT(CASE WHEN ISNULL(od.CD_TYPE, '') = 'B' THEN 1 END) AS CD_TYPE_BB_CNT , COUNT(CASE ISNULL(od.INSPECTION_YN, '') WHEN 'Y' THEN 1 END) AS INSPECTION_CNT , COUNT(CASE ISNULL(odAdd.SE_INSPECTION_YN, '') WHEN 'Y' THEN 1 END) AS SE_INSPECTION_CNT , COUNT(CASE ISNULL(odAdd.XRAY_YN, '') WHEN 'Y' THEN 1 END) AS XRAY_CNT , COUNT(CASE ISNULL(odAdd.DROP_YN, '') WHEN 'Y' THEN 1 END) AS DROP_CNT
, (SELECT COUNT(*) FROM ( SELECT hod.OD_JOB_NO FROM TB_ECM_OD hod LEFT JOIN TB_ECM_OD_HOLD hld ON hod.OD_JOB_NO = hld.OD_JOB_NO WHERE hod.MASTER_OD_JOB_NO = od.MASTER_OD_JOB_NO AND hod.BL_TYPE_MH = MIN(od.BL_TYPE_MH) AND hld.HOLD_RELEASE_YN = 'N' GROUP BY hod.OD_JOB_NO ) A ) AS HOLD_CNT , COUNT(CASE WHEN ISNULL(odAdnor.ABNORMAL_CODE, '') != '' THEN 1 END) AS MFN_CNT , COUNT(CASE WHEN ISNULL(odAdd.CARRYIN_DATE, '') != '' THEN 1 END) AS CARRYIN_CNT , COUNT(CASE WHEN ISNULL(odAdd.CARRYOUT_DATE, '') != '' THEN 1 END) AS CARRYOUT_CNT , COUNT(CASE ISNULL(odAdd.CLEARANCE_YN, '') WHEN 'Y' THEN 1 END) AS CLEARANCE_CNT
, COUNT(CASE WHEN ISNULL(odAdd.CLEARANCE_YN, '') != 'Y' THEN 1 END) AS BEFORE_CLEARANCE_CNT , COUNT(CASE WHEN ISNULL(odAdd.DELIVERY_RECV_DATE, '') != '' THEN 1 END) AS DELIVERY_RECV_CNT , COUNT(CASE WHEN ISNULL(odAdd.DELIVERY_YN, '') = 'Y' THEN 1 END) AS DELIVERY_CNT , COUNT(CASE WHEN ISNULL(odAdd.STOCK_YN, '') = 'Y' THEN 1 END) AS STOCK_CNT , COUNT(CASE WHEN odAdd.DROP_YN = 'Y' OR odAdd.ABNORMAL_DATE IS NOT NULL THEN 1 END) AS UNUSUAL_CNT , COUNT(CASE WHEN ISNULL(odAdd.WH_CARRYOUT_DATE,'') = '' THEN 1 END) AS NO_RELEASE_CNT , COUNT(od.HBL_NO) - COUNT(CASE WHEN ISNULL(odAdd.CARRYIN_DATE, '') != '' THEN 1 END) AS NO_CARRYIN_CNT FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_ADDITIONAL odAdd ON od.OD_JOB_NO = odAdd.OD_JOB_NO LEFT JOIN TB_ECM_OD_ABNORMAL odAdnor ON od.OD_JOB_NO = odAdnor.OD_JOB_NO AND odAdnor.ABNORMAL_CODE = 'MFN' WHERE od.ENT_CODE = #{srchEntCode} AND od.BL_TYPE_MH = 'H'
AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP' AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'EXP' AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP' AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'EXP'
AND od.${srchDateGbn} >= CONVERT(DATETIME, #{srchStartDate} + ' 00:00:00') AND od.${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}))
AND od.${srchNoType} LIKE CONCAT('%',#{srchNo},'%')
AND od.${srchNoType} IN (#{item})
AND od.${srchNoType} = #{srchNo}
AND od.${srchCusType} LIKE CONCAT('%',#{srchCus},'%')
AND od.${srchCusType} = #{srchCus}
AND dbo.Cryptography(od.OD_JOB_NO, od.${srchCusType}_ENC, 1) = #{srchConsigneeName}
AND od.${srchCusType} = #{srchConsigneeName}
AND od.${srchOrigDestType} LIKE CONCAT('%',#{srchOrigDest},'%')
AND od.${srchOrigDestType} = #{srchOrigDest}
GROUP BY od.MASTER_OD_JOB_NO

/* CoioMapper.selectCoioLocationList : 반입/반출(location) 조회 */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT MAX(ISNULL(odAdd.WH_LOCATION,'')) AS WH_LOCATION , (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = MAX(od.ENT_CODE) AND GROUP_CODE = 'WH_LOCATION' AND CODE = MAX(ISNULL(odAdd.WH_LOCATION,''))) AS WH_LOCATION_NAME , MAX(ISNULL(od.CUST_CODE_LV1, '')) AS AGENT_CODE , COUNT(ISNULL(od.HBL_NO, 0)) AS HBL_CNT , SUM(od.PIECES) AS PIECES , SUM(od.GWT) AS GWT , MAX(ISNULL(od.AR_DATE, '')) AS AR_DATE
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL odAdd ON od.OD_JOB_NO = odAdd.OD_JOB_NO WHERE od.ENT_CODE = #{srchEntCode} AND od.BL_TYPE_MH = 'H' AND ISNULL(odAdd.WH_LOCATION, '') != ''
AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP' AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'EXP' AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP' AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'EXP'
AND od.${srchDateGbn} >= CONVERT(DATETIME, #{srchStartDate} + ' 00:00:00') AND od.${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}))
AND od.${srchType} IN (#{item})
AND od.${srchType} = #{srchNo}
AND od.${srchType} = #{srchCustCodeLv1}
AND od.${srchType} = #{srchConsigneeName}
AND odAdd.WH_LOCATION = #{srchWhLocation}
GROUP BY odAdd.WH_LOCATION, od.CUST_CODE_LV1

/* CoioMapper.selectCoioLocationSubList : 반입/반출(location) sub 조회 */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT od.HBL_NO , od.AR_DATE , odAdd.CARRYIN_DATE , odAdd.CARRYOUT_DATE , ( SELECT TOP 1 A.POD_DATE FROM( SELECT POD_DATE FROM TB_ECM_POD WHERE POD_STATUS = 'ECM240' AND OD_JOB_NO = od.OD_JOB_NO UNION ALL SELECT POD_DATE FROM TB_ECM_POD_03 WHERE POD_STATUS = 'ECM240' AND OD_JOB_NO = od.OD_JOB_NO ) A ) AS CLEARANCE_FINISH_DATE , od.CONSIGNEE_NAME_LOC , od.MRN , ISNULL(od.PIECES, 0) AS PIECES , ISNULL(od.GWT, 0) AS GWT , ISNULL(od.CD_TYPE, '') AS CD_TYPE , CONVERT(CHAR(19),odAdd.STOCK_DATE_TIME,20) as STOCK_DATE_TIME , (SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = od.ENT_CODE AND USER_ID = odAdd.STOCK_USER_ID) AS STOCK_USER_ID , (SELECT TOP 1 MIN(HOLD_RELEASE_YN) OVER(PARTITION BY OD_JOB_NO) FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO) AS HOLD_RELEASE_YN , CASE WHEN ISNULL((SELECT TOP 1 HOLD_CODE FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'N'), '') IN ('', '4') THEN (SELECT TOP 1 HOLD_REASON FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'N') ELSE (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'HOLD_CODE' AND CODE = (SELECT TOP 1 HOLD_CODE FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO = od.OD_JOB_NO AND HOLD_RELEASE_YN = 'N')) END AS HOLD_REASON , ISNULL(od.COMMODITY_ITEM, '') AS COMMODITY_ITEM , od.ORIG_CODE , ISNULL(od.CUST_CODE_LV1, '') AS AGENT_CODE , od.CUST_CODE_LV2 , od.SHIPPER_NAME , od.REGISTER_USER_ID , od.REGISTER_DATE_TIME , od.UPDATE_USER_ID , od.UPDATE_DATE_TIME , ISNULL(odAdd.WH_LOCATION,'') AS WH_LOCATION , (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'WH_LOCATION' AND CODE = odAdd.WH_LOCATION) AS WH_LOCATION_NAME
, odAdd.LAST_POD_STATUS ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'ECM_DELIVERY_CODE' AND CODE = od.DELIVERY_CODE) AS DELIVERY_NAME ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CB_CODE) AS CB_NAME
, od.MBL_NO , od.PO_DATE
, od.OD_JOB_NO
,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_HP_ENC, 1) AS CONSIGNEE_HP ,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) AS CONSIGNEE_TEL
,od.CONSIGNEE_HP ,od.CONSIGNEE_TEL
FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_ADDITIONAL odAdd ON od.OD_JOB_NO = odAdd.OD_JOB_NO WHERE od.ENT_CODE = #{srchEntCode} AND odAdd.WH_CARRYOUT_DATE IS NULL AND odAdd.CARRYOUT_USER_ID IS NULL
AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP' AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'EXP' AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP' AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'EXP'
AND od.${srchDateGbn} >= CONVERT(DATETIME, #{srchStartDate} + ' 00:00:00') AND od.${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}))
AND od.${srchCusType} LIKE CONCAT('%',#{srchCus},'%')
AND od.${srchCusType} = #{srchCus}
AND od.${srchCusType} IS NULL
AND odAdd.WH_LOCATION = #{srchWhLocation}
AND od.${srchType} IN (#{item})
AND od.${srchType} = #{srchNo}
AND od.${srchType} = #{srchCustCodeLv1}
AND od.${srchType} = #{srchConsigneeName}
